-- composition of rule kernels Coroutines x GroupByOrder (sqlite), template exists
SELECT count(*) FROM (SELECT '{"k": -1, "a": [1, 2, 3]}' AS c0 FROM tl AS a1 WHERE ((NULLIF (((SELECT JSON_GROUP_ARRAY (a2.c0 ORDER BY a2.c0) FROM v0 AS a2) ->> 'a'), a1.c1), FALSE) <> (a1.c1, TRUE)) GROUP BY a1.c0) AS ka WHERE EXISTS (SELECT 1 FROM (WITH t(g, x) AS ( SELECT 1, '9007199254740994abc' ) SELECT NULL FROM t GROUP BY g ORDER BY g) AS kb);
-- pgfuzz:check kernel:exists SELECT CASE WHEN (SELECT count(*) FROM (WITH t(g, x) AS ( SELECT 1, '9007199254740994abc' ) SELECT NULL FROM t GROUP BY g ORDER BY g) AS kb) > 0 THEN (SELECT count(*) FROM (SELECT '{"k": -1, "a": [1, 2, 3]}' AS c0 FROM tl AS a1 WHERE ((NULLIF (((SELECT JSON_GROUP_ARRAY (a2.c0 ORDER BY a2.c0) FROM v0 AS a2) ->> 'a'), a1.c1), FALSE) <> (a1.c1, TRUE)) GROUP BY a1.c0) AS ka) ELSE 0 END
